from math import gcd
from functools import lru_cache

def compute_grundy(n):
    """Compute Grundy values up to n by brute force."""
    g = [0] * (n + 1)
    for x in range(1, n + 1):
        reachable = set()
        for y in range(1, x + 1):
            if gcd(x, y) == 1:
                reachable.add(g[x - y])
        # mex
        mex = 0
        while mex in reachable:
            mex += 1
        g[x] = mex
    return g

